namespace Pyrlyn.Config.Layered.Tests;

public sealed class TomlEditorTests
{
    private const string Commented = """
        # rtok config
        # generated by config init

        name = "rtok"

        [proxy]
        # The port.
        port   = 8080   # keep this comment
        # openai_upstream = "https://api.openai.com"
        # missing_key is described here = not an assignment

        [log]
        banner = '''
        [proxy]
        # missing_key = 1
        '''
        level = "info" # info | debug

        """;

    [Fact]
    public void ALiveKeyChangesOnlyItsValue()
    {
        var edited = TomlEditor.Set(Commented, "proxy.port", 9090L);

        Assert.Equal(Commented.Replace("8080", "9090", StringComparison.Ordinal), edited);
    }

    [Fact]
    public void ACommentedAssignmentIsUncommentedInPlace()
    {
        var edited = TomlEditor.Set(Commented, "proxy.openai_upstream", "http://local");

        Assert.Equal(
            Commented.Replace(
                "# openai_upstream = \"https://api.openai.com\"",
                "openai_upstream = \"http://local\"",
                StringComparison.Ordinal
            ),
            edited
        );
    }

    [Fact]
    public void TextInsideAMultilineStringIsNeverEdited()
    {
        var edited = TomlEditor.Set(Commented, "proxy.missing_key", 2L);

        Assert.Equal(
            Commented.Replace(
                "# keep this comment\n",
                "# keep this comment\nmissing_key = 2\n",
                StringComparison.Ordinal
            ),
            edited
        );
    }

    [Fact]
    public void ANewTableIsAppended()
    {
        var edited = TomlEditor.Set(Commented, "web.port", 3000L);

        Assert.Equal(Commented + "\n[web]\nport = 3000\n", edited);
    }

    [Fact]
    public void ARootKeyGoesAfterTheLastRootKey()
    {
        var edited = TomlEditor.Set(Commented, "version", 2L);

        Assert.Equal(
            Commented.Replace(
                "name = \"rtok\"\n",
                "name = \"rtok\"\nversion = 2\n",
                StringComparison.Ordinal
            ),
            edited
        );
        Assert.Equal("version = 2\n[a]\nb = 1\n", TomlEditor.Set("[a]\nb = 1\n", "version", 2L));
        Assert.Equal("a = 1\nb = true\n", TomlEditor.Set("a = 1", "b", value: true));
        Assert.Equal("[a]\nb = 1\n", TomlEditor.Set("[a]", "a.b", 1L));
        Assert.Equal("[a]\nb = 1\nc = 2\n", TomlEditor.Set("[a]\nb = 1", "a.c", 2L));
    }

    [Fact]
    public void AKeyUnderADottedTableStaysDotted()
    {
        Assert.Equal(
            "[a]\nb.c = 1\nb.d = [1, 2]\n",
            TomlEditor.Set("[a]\nb.c = 1\n", "a.b.d", new List<long> { 1, 2 })
        );
    }

    [Fact]
    public void CrlfFilesStayCrlf()
    {
        Assert.Equal(
            "[a]\r\nb = 1\r\nc = \"x\"\r\n",
            TomlEditor.Set("[a]\r\nb = 1\r\n", "a.c", "x")
        );
    }

    [Fact]
    public void AKeyThroughAScalarIsRefusedWithItsLine()
    {
        var e = Assert.Throws<ConfigFileException>(() =>
            TomlEditor.Set(Commented, "proxy.port.x", 1L, "config.toml")
        );
        Assert.Equal("config.toml:8: proxy.port is not a table", e.Message);
    }

    [Fact]
    public void InvalidTomlIsRefused()
    {
        var e = Assert.Throws<ConfigFileException>(() =>
            TomlEditor.Set("[a\n", "a.b", 1L, "config.toml")
        );
        Assert.Equal(1, e.Line);
    }

    [Fact]
    public void ValuesAreWrittenAsToml()
    {
        Assert.Equal("\"a\\\"b\"", TomlText.Format("a\"b"));
        Assert.Equal("1.5", TomlText.Format(1.5));
        Assert.Equal("[\"x\", 2, false]", TomlText.Format(new object[] { "x", 2L, false }));
        Assert.Equal(8080L, TomlText.ParseValueOrString("8080"));
        Assert.Equal("not toml", TomlText.ParseValueOrString("not toml"));
        Assert.Equal("quoted", TomlText.ParseValueOrString("\"quoted\""));
    }
}
